-- =====================================================================
-- Hub de Projetos · PADRÃO PS DE ORÇAMENTO (EAP + biblioteca de serviços de referência + tipos de local)
-- Origem: mapeamento linha a linha do orçamento real "Gaia 53 V31" (exemplo — não é o padrão em si)
-- Blueprint: vertical hub_projetos, telas 333 (padrão) · 334 (importador) · complementos 8/314/315/316
-- Conteúdo: 178 nós de EAP · 1536 serviços de referência · 18 bibliotecas por ramo · 6 tipos de local
-- Ramo: construtora vê edificacao (obra inteira); prestadora vê só o ramo dela (gesso, piso, elétrica…); escritório vê arquitetura_projetos.
-- Regra: a biblioteca de referência é GLOBAL e SOMENTE LEITURA. A empresa só copia o serviço
--        que usar (fn_projetos_usar_servico_padrao). NUNCA entra em projetos_servicos is_publico
--        (o importador público copiaria os 1536 serviços para cada empresa e zeraria o custo).
-- =====================================================================
begin;

create table if not exists public.projetos_eap_padrao (
  codigo        text primary key,
  parent_codigo text references public.projetos_eap_padrao(codigo),
  nivel         smallint not null check (nivel between 1 and 3),
  nome          text not null,
  ordem         int  not null,
  versao        text not null default 'PS-EAP-2026.1',
  ativo         boolean not null default true,
  created_at    timestamptz not null default now()
);
comment on table public.projetos_eap_padrao is 'Hub · EAP padrão PS (etapa → subetapa → grupo). Local (pavimento/unidade/ambiente) NÃO é nível da EAP: é dimensão do item. Blueprint hub_projetos tela 333.';

create table if not exists public.projetos_ref_ramo (
  codigo     text primary key,
  nome       text not null,
  modo       text not null check (modo in ('construtora','prestadora','escritorio')),
  descricao  text not null,
  eap_prefixos text[] not null,
  ordem      int  not null
);
comment on table public.projetos_ref_ramo is 'Hub · bibliotecas por ramo. Construtora (e pessoa física, resumido) vê edificacao = obra inteira; prestadora vê só o(s) ramo(s) da sua especialidade (gesso, piso, elétrica…); escritório vê arquitetura_projetos. Blueprint hub_projetos tela 333 / governadora 328.';

create table if not exists public.projetos_local_tipo (
  codigo    text primary key,
  nome      text not null,
  descricao text not null,
  ordem     int  not null
);
comment on table public.projetos_local_tipo is 'Hub · tipos de local da estrutura física da obra (projetos_obra_estrutura). Blueprint hub_projetos telas 314/333.';

create table if not exists public.projetos_ref_servico_padrao (
  codigo              text primary key,
  eap_codigo          text not null references public.projetos_eap_padrao(codigo),
  nome                text not null,
  unidade             text not null,
  custo_material_ref  numeric(14,4) not null default 0,
  custo_mao_obra_ref  numeric(14,4) not null default 0,
  custo_material_min  numeric(14,4),
  custo_material_max  numeric(14,4),
  custo_mao_obra_min  numeric(14,4),
  custo_mao_obra_max  numeric(14,4),
  ramos               text[] not null default '{edificacao}',
  especifico_obra     boolean not null default false,
  ocorrencias_ref     int,
  n_locais_ref        int,
  fonte               text not null default 'gaia53_v31',
  fonte_descricao     text not null default 'Orçamento real Gaia 53 V31 (edifício misto, SC, 2026) · mediana por serviço · referência, não preço de venda',
  versao              text not null default 'PS-EAP-2026.1',
  ativo               boolean not null default true,
  created_at          timestamptz not null default now()
);
create index if not exists idx_ref_servico_padrao_eap on public.projetos_ref_servico_padrao(eap_codigo);
create index if not exists idx_ref_servico_padrao_ramos on public.projetos_ref_servico_padrao using gin (ramos);
comment on table public.projetos_ref_servico_padrao is 'Hub · biblioteca de serviços de referência PS (global, somente leitura). Empresa copia sob demanda via fn_projetos_usar_servico_padrao. Blueprint hub_projetos tela 333.';

alter table public.projetos_ref_ramo          enable row level security;
drop policy if exists ref_ramo_leitura on public.projetos_ref_ramo;
create policy ref_ramo_leitura on public.projetos_ref_ramo for select to authenticated using (true);
revoke insert, update, delete on public.projetos_ref_ramo from anon, authenticated;
grant select on public.projetos_ref_ramo to authenticated;
alter table public.projetos_eap_padrao        enable row level security;
alter table public.projetos_local_tipo        enable row level security;
alter table public.projetos_ref_servico_padrao enable row level security;
drop policy if exists eap_padrao_leitura on public.projetos_eap_padrao;
create policy eap_padrao_leitura on public.projetos_eap_padrao for select to authenticated using (true);
drop policy if exists local_tipo_leitura on public.projetos_local_tipo;
create policy local_tipo_leitura on public.projetos_local_tipo for select to authenticated using (true);
drop policy if exists ref_servico_padrao_leitura on public.projetos_ref_servico_padrao;
create policy ref_servico_padrao_leitura on public.projetos_ref_servico_padrao for select to authenticated using (true);
revoke insert, update, delete on public.projetos_eap_padrao, public.projetos_local_tipo, public.projetos_ref_servico_padrao from anon, authenticated;
grant select on public.projetos_eap_padrao, public.projetos_local_tipo, public.projetos_ref_servico_padrao to authenticated;

alter table public.projetos_servicos add column if not exists eap_codigo text references public.projetos_eap_padrao(codigo);
alter table public.projetos_servicos add column if not exists ref_padrao_codigo text references public.projetos_ref_servico_padrao(codigo);
create unique index if not exists uq_projetos_servicos_ref_padrao on public.projetos_servicos(company_id, ref_padrao_codigo) where ref_padrao_codigo is not null and deleted_at is null;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;

on conflict (codigo) do nothing;


-- Copia UM serviço de referência para a empresa (idempotente). Nunca chama fn_projetos_recalcular_custo_servico:
-- o serviço de referência não tem BOM e o recálculo zeraria o custo.
create or replace function public.fn_projetos_usar_servico_padrao(p_company_id uuid, p_ref_codigo text)
returns uuid language plpgsql security definer set search_path to 'public','pg_temp' as $f$
declare v_ref public.projetos_ref_servico_padrao%rowtype; v_id uuid;
begin
  perform public.fn__guarda_empresa(p_company_id);
  select * into v_ref from public.projetos_ref_servico_padrao where codigo = p_ref_codigo and ativo;
  if not found then raise exception 'Serviço de referência % não encontrado', p_ref_codigo using errcode = 'P0002'; end if;
  select id into v_id from public.projetos_servicos
   where company_id = p_company_id and ref_padrao_codigo = p_ref_codigo and deleted_at is null limit 1;
  if v_id is not null then return v_id; end if;
         custo_material, custo_mao_obra, custo_equipamento, custo_unitario_total,
         is_publico, source_type, source_ref, eap_codigo, ref_padrao_codigo, observacoes)
  select p_company_id, v_ref.codigo, left(v_ref.nome, 300), v_ref.nome, v_ref.unidade, e1.nome,
         v_ref.custo_material_ref, v_ref.custo_mao_obra_ref, 0, v_ref.custo_material_ref + v_ref.custo_mao_obra_ref,
         false, 'padrao_ps', 'ref:' || v_ref.codigo || '@' || v_ref.versao, v_ref.eap_codigo, v_ref.codigo,
         'Da biblioteca padrão PS (' || v_ref.fonte_descricao || '). Ajuste o custo à sua realidade.'
    from public.projetos_eap_padrao e1 where e1.codigo = split_part(v_ref.eap_codigo, '.', 1)
  on conflict (company_id, codigo) do update set ref_padrao_codigo = excluded.ref_padrao_codigo, eap_codigo = excluded.eap_codigo
  returning id into v_id;
  return v_id;
end $f$;
revoke all on function public.fn_projetos_usar_servico_padrao(uuid, text) from public, anon;
grant execute on function public.fn_projetos_usar_servico_padrao(uuid, text) to authenticated;

-- Prova (RD-38): a migração falha se a contagem não bater.
do $$ begin
  if (select count(*) from public.projetos_eap_padrao) < 178 then raise exception 'EAP padrão incompleta'; end if;
  if (select count(*) from public.projetos_ref_servico_padrao) < 1536 then raise exception 'Biblioteca padrão incompleta'; end if;
  if (select count(*) from public.projetos_local_tipo) < 6 then raise exception 'Tipos de local incompletos'; end if;
  if (select count(*) from public.projetos_ref_ramo) < 18 then raise exception 'Ramos incompletos'; end if;
  if exists (select 1 from public.projetos_ref_servico_padrao where cardinality(ramos) < 2) then raise exception 'Serviço sem ramo de prestador/escritório'; end if;
end $$;

commit;
